-- composition of rule kernels L:common_sub_expression_eliminate x L:push_down_filter (datafusion), template cte_twice
WITH ka AS (SELECT 6 AS c0, COALESCE (CASE WHEN TRUE THEN ARRAY[(SELECT MAX (a2.c0) FROM t0 AS a2 WHERE (29 >= a2.c0))] ELSE make_array(1, 2, 3) END, make_array(NULL, 1)) AS c1 FROM tl AS a1), kb AS (SELECT CASE a1.c4 WHEN make_array(1, 2, 3, 4) THEN 5e-324::float8 WHEN a1.c4 THEN 0.0::float8 ELSE 0.5::float8 END AS c0 FROM (t3 AS a1 INNER JOIN ti AS a2 ON (a1.c0 = a2.c0)) UNION ALL SELECT 100.0::float8 AS c0) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (SELECT 6 AS c0, COALESCE (CASE WHEN TRUE THEN ARRAY[(SELECT MAX (a2.c0) FROM t0 AS a2 WHERE (29 >= a2.c0))] ELSE make_array(1, 2, 3) END, make_array(NULL, 1)) AS c1 FROM tl AS a1) AS ka) + (SELECT count(*) FROM (SELECT CASE a1.c4 WHEN make_array(1, 2, 3, 4) THEN 5e-324::float8 WHEN a1.c4 THEN 0.0::float8 ELSE 0.5::float8 END AS c0 FROM (t3 AS a1 INNER JOIN ti AS a2 ON (a1.c0 = a2.c0)) UNION ALL SELECT 100.0::float8 AS c0) AS kb)
